17	import { normalizeName, similarity } from '@/shared/lib/stringUtils';
18	
19	/** Item extraído (parcial) que será casado com o catálogo. */
20	export interface MatchableItem {
21	  name: string;
22	  /** Título/cabeçalho da seção a que o item pertence (ex.: "Bolos no Pote"). */
23	  category?: string;
24	}
