26	/** Produto de catálogo (forma mínima — qualquer objeto com `id` e `nome`). */
27	export interface MatchableProduct {
28	  id: number;
29	  nome: string;
30	}
31	
32	/** Threshold padrão de match fuzzy (alinhado à produção diária). */
33	export const DEFAULT_MATCH_THRESHOLD = 0.72;
34	
35	/** Acima disto, um match é forte o bastante pra travar mesmo sem coerência de título. */
36	export const HIGH_CONFIDENCE = 0.92;
37	
38	// Palavras de ligação ignoradas ao comparar o título da seção com o nome do produto.
39	const CATEGORY_STOPWORDS = new Set([
40	  'de', 'do', 'da', 'no', 'na', 'com', 'e', 'a', 'o', 'os', 'as', 'em', 'sem', 'ao', 'dos', 'das',
41	]);
42	
43	/** Reduz plural simples do português ("bolos" → "bolo", "minis" → "mini"). */
44	const stem = (t: string): string => (t.length > 4 && t.endsWith('s') ? t.slice(0, -1) : t);
45	
46	/**
47	 * Constrói os nomes-candidatos para o match fuzzy de um item.
48	 *
49	 * Sempre inclui o nome cru. Quando há um título de seção significativo e o nome
50	 * ainda não começa com ele, inclui também o nome qualificado pela categoria
51	 * (`"categoria sabor"`), para resgatar o produto completo.
52	 */
53	export function buildMatchCandidates(item: MatchableItem): string[] {
54	  const name = (item.name || '').trim();
55	  const cat = (item.category || '').trim();
56	  const candidates = [name];
57	  const catNorm = normalizeName(cat);
58	  if (catNorm && catNorm !== 'geral' && !normalizeName(name).startsWith(catNorm)) {
59	    candidates.push(`${cat} ${name}`.trim());
60	  }
61	  return candidates;
62	}
63	
64	/**
65	 * O produto casado é coerente com a categoria/título da seção do item?
66	 *
67	 * Verdadeiro quando o nome do produto contém a maioria dos tokens
68	 * significativos do título (tolerando plural). Itens sem categoria significativa
69	 * são sempre coerentes (não há título a violar).
70	 */
71	export function isCategoryConsistent(
72	  item: MatchableItem,
73	  product: Pick<MatchableProduct, 'nome'>,
74	): boolean {
75	  const cat = normalizeName((item.category || '').replace(/[/|]+/g, ' '));
76	  if (!cat || cat === 'geral') return true;
77	
78	  const prodNorm = normalizeName(product.nome);
79	  const tokens = cat
80	    .split(' ')
81	    .filter((t) => t.length >= 3 && !CATEGORY_STOPWORDS.has(t))
82	    .map(stem);
83	  if (tokens.length === 0) return true;
84	
85	  const hits = tokens.filter((t) => prodNorm.includes(t)).length;
86	  return hits >= Math.ceil(tokens.length / 2);
