107	  item: MatchableItem,
108	  catalog: T[],
109	): CategoryAwareMatch<T> {
110	  const candidates = buildMatchCandidates(item);
111	  let best: T | null = null;
112	  let bestScore = 0;
113	  let via: 'bare' | 'category' = 'bare';
114	
115	  candidates.forEach((cand, ci) => {
116	    for (const p of catalog) {
117	      const sim = similarity(cand, p.nome);
118	      if (sim > bestScore) {
119	        bestScore = sim;
120	        best = p;
121	        via = ci === 0 ? 'bare' : 'category';
122	      }
123	    }
124	  });
125	
126	  return {
127	    product: best,
128	    score: bestScore,
129	    categoryConsistent: best ? isCategoryConsistent(item, best) : false,
130	    via,
131	  };
132	}
133	
134	/**
135	 * Decide se um match deve travar automaticamente, ou ir pra revisão manual.
136	 *
137	 * Política "perguntar, não chutar": exige passar o threshold E (match forte OU
138	 * coerente com o título). Um match de score médio incoerente com o cabeçalho
139	 * da seção vai pra revisão em vez de amarrar no produto errado em silêncio.
140	 */
