describe('bestCatalogMatch — regressão A4: milho/Caseirinhos (nunca trava Milho insumo)', () => {
  it('"milho" sob "Caseirinhos" sugere "Mini Caseirinho Milho", NUNCA "Milho" insumo', () => {
    // Caso real: "milho" cru sob seção "Caseirinhos" casava score 1.0 com o insumo
    // "Milho" (id 9) e travava errado. Com a preferência coerente, retorna o produto
    // correto da seção. O score é < 0.72 (string edit), então vai pra revisão (não
    // trava) — mas JÁ com "Mini Caseirinho Milho" pré-selecionado.
    const m = bestCatalogMatch({ name: 'milho', category: 'Caseirinhos' }, CATALOG);
    expect(m.product?.nome).toBe('Mini Caseirinho Milho');
    expect(m.product?.id).toBe(10);
    expect(m.categoryConsistent).toBe(true);
    expect(m.score).toBeLessThan(DEFAULT_MATCH_THRESHOLD);
    expect(shouldAutoLock(m)).toBe(false); // vai pra revisão com sugestão certa
  });

  it('"Mini Caseirinho Milho" sob "Caseirinhos" — exato — trava (A1 parser herdado)', () => {
    // Quando o parser herda corretamente "Mini Caseirinho Milho" (via CATEGORY_PREFIX_MAP
    // + repairItemName da edge function), o score é 1.0 e shouldAutoLock trava.
    const m = bestCatalogMatch(
      { name: 'Mini Caseirinho Milho', category: 'Caseirinhos' },
      CATALOG,
    );
    expect(m.product?.nome).toBe('Mini Caseirinho Milho');
    expect(m.categoryConsistent).toBe(true);
    expect(m.score).toBeGreaterThanOrEqual(DEFAULT_MATCH_THRESHOLD);
    expect(shouldAutoLock(m)).toBe(true);
  });

  it('score 1.0 incoerente via "bare" NÃO trava — bypass removido', () => {
    // Antes: shouldAutoLock tinha "if (score >= 0.92) return true" que travava
    // "milho → Milho" (score 1.0) independente de categoryConsistent.
    // Agora: incoerente + bare nunca trava, independente do score.
    expect(
      shouldAutoLock({
        product: { id: 9, nome: 'Milho' },
        score: 1,
        categoryConsistent: false,
        via: 'bare',
      }),
    ).toBe(false);
  });
});

